{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, extname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const databasePath = resolve(process.env.DB_PATH || join(root, 'workboard.sqlite'));
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
    default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High')),
    due_date TEXT
  );
`);
// Older databases from Task 001/002 have no archive column.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!projectColumns.some((column) => column.name === 'default_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
// Add the Task 006 field to databases created by earlier checkpoints.
const taskColumns = database.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!taskColumns.some((column) => column.name === 'due_date')) {
  database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
}

function isValidDueDate(value) {
  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return false;
  const [, yearText, monthText, dayText] = match;
  const year = Number(yearText);
  const month = Number(monthText);
  const day = Number(dayText);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  return day <= daysInMonth;
}

const contentTypes = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try { return JSON.parse(body); } catch { return null; }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }

  if (url.pathname === '/api/projects' && request.method === 'GET') {
    const projects = database.prepare(`
      SELECT p.id, p.name, p.archived, p.default_priority AS defaultPriority,
        COUNT(t.id) AS totalCount,
        COALESCE(SUM(t.completed), 0) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id
    `).all().map((project) => ({ ...project, archived: Boolean(project.archived), totalCount: Number(project.totalCount), completedCount: Number(project.completedCount) }));
    return sendJson(response, 200, projects);
  }
  if (url.pathname === '/api/projects' && request.method === 'POST') {
    const body = await readJson(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && request.method === 'GET') {
    const project = database.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, { ...project, archived: Boolean(project.archived) }) : sendJson(response, 404, { error: 'Project not found' });
  }

  const defaultPriorityMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/default-priority$/);
  if (defaultPriorityMatch && request.method === 'PATCH') {
    const projectId = Number(defaultPriorityMatch[1]);
    const body = await readJson(request);
    if (!['Low', 'Normal', 'High'].includes(body?.priority)) return sendJson(response, 400, { error: 'Default task priority is invalid' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot change their default task priority' });
    database.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(body.priority, projectId);
    return sendJson(response, 200, { id: projectId, defaultPriority: body.priority });
  }

  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/name$/);
  if (renameMatch && request.method === 'PATCH') {
    const body = await readJson(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const projectId = Number(renameMatch[1]);
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot be renamed' });
    database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, projectId);
    return sendJson(response, 200, { id: projectId, name });
  }

  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (archiveMatch && request.method === 'PATCH') {
    const body = await readJson(request);
    if (typeof body?.archived !== 'boolean') return sendJson(response, 400, { error: 'Archive state is required' });
    const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(body.archived ? 1 : 0, Number(archiveMatch[1]));
    if (!result.changes) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, { id: Number(archiveMatch[1]), archived: body.archived });
  }

  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    const projectExists = database.prepare('SELECT archived, default_priority FROM projects WHERE id = ?').get(projectId);
    if (!projectExists) return sendJson(response, 404, { error: 'Project not found' });
    if (request.method === 'GET') {
      const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY id').all(projectId)
        .map((task) => ({ ...task, completed: Boolean(task.completed) }));
      return sendJson(response, 200, tasks);
    }
    if (request.method === 'POST') {
      if (projectExists.archived) return sendJson(response, 409, { error: 'Archived projects cannot have new tasks' });
      const body = await readJson(request);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) return sendJson(response, 400, { error: 'Task title is required' });
      const result = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)').run(projectId, title, projectExists.default_priority);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false, priority: projectExists.default_priority });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  const taskDueDateMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/due-date$/);
  const taskPriorityMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/priority$/);
  const taskNameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/title$/);
  if (taskNameMatch && request.method === 'PATCH') {
    const projectId = Number(taskNameMatch[1]);
    const taskId = Number(taskNameMatch[2]);
    const body = await readJson(request);
    const title = typeof body?.title === 'string' ? body.title.trim() : '';
    if (!title) return sendJson(response, 400, { error: 'Task title is required' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived project tasks cannot be changed' });
    const result = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?').run(title, taskId, projectId);
    if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
    return sendJson(response, 200, { id: taskId, projectId, title });
  }
  if (taskPriorityMatch && request.method === 'PATCH') {
    const projectId = Number(taskPriorityMatch[1]);
    const taskId = Number(taskPriorityMatch[2]);
    const body = await readJson(request);
    if (!['Low', 'Normal', 'High'].includes(body?.priority)) return sendJson(response, 400, { error: 'Task priority is invalid' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived project tasks cannot be changed' });
    const result = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?').run(body.priority, taskId, projectId);
    if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
    return sendJson(response, 200, { id: taskId, projectId, priority: body.priority });
  }
  if (taskDueDateMatch && request.method === 'PATCH') {
    const projectId = Number(taskDueDateMatch[1]);
    const taskId = Number(taskDueDateMatch[2]);
    const body = await readJson(request);
    if (typeof body?.dueDate !== 'string') return sendJson(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
    const dueDate = body.dueDate.trim();
    if (dueDate && !isValidDueDate(dueDate)) return sendJson(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived project tasks cannot be changed' });
    const result = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?').run(dueDate || null, taskId, projectId);
    if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
    return sendJson(response, 200, { id: taskId, projectId, dueDate: dueDate || null });
  }
  if (taskMatch && request.method === 'PATCH') {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const body = await readJson(request);
    if (typeof body?.completed !== 'boolean') return sendJson(response, 400, { error: 'Completion state is required' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 409, { error: 'Archived project tasks cannot be changed' });
    const result = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
    if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
    return sendJson(response, 200, { id: taskId, projectId, completed: body.completed });
  }

  const requestedPath = url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname)
    ? 'index.html'
    : url.pathname.replace(/^\//, '');
  const filePath = resolve(root, 'public', requestedPath);
  if (!filePath.startsWith(resolve(root, 'public') + '/') && filePath !== resolve(root, 'public', 'index.html')) {
    response.writeHead(404).end();
    return;
  }
  try {
    const content = readFileSync(filePath);
    response.writeHead(200, { 'content-type': contentTypes[extname(filePath)] || 'application/octet-stream' });
    response.end(content);
  } catch {
    response.writeHead(404).end();
  }
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong');
  return data;
}

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

function go(path) {
  history.pushState({}, '', path);
  render();
}

async function renderList() {
  app.replaceChildren(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', undefined, { id: 'project-name', name: 'name', type: 'text' });
  const submit = element('button', 'Create project', { type: 'submit' });
  const alert = element('p', '', { role: 'alert', hidden: '' });
  const rows = element('section', undefined, { 'aria-label': 'Projects' });
  const filterLabel = element('label', 'Project filter', { for: 'project-filter' });
  const filter = element('select', undefined, { id: 'project-filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', value, { value: value.toLowerCase() }));
  form.append(label, input, submit);
  app.append(form, alert, filterLabel, filter, rows);

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    try {
      await request('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
      alert.hidden = true;
      input.value = '';
      await loadProjects();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  });

  async function loadProjects() {
    try {
    const projects = await request('/api/projects');
    rows.replaceChildren();
    for (const project of projects) {
      if (project.archived !== (filter.value === 'archived')) continue;
      const row = element('article', undefined, { 'data-testid': 'project-row' });
      const summary = element('span', `${project.completedCount}/${project.totalCount} completed`, { 'data-testid': 'project-summary' });
      row.append(element('span', project.name), summary);
      const open = element('button', 'Open project', { type: 'button' });
      open.addEventListener('click', () => go(`/projects/${project.id}`));
      row.append(open);
      const archive = element('button', project.archived ? 'Restore project' : 'Archive project', { type: 'button' });
      archive.addEventListener('click', async () => {
        try {
          await request(`/api/projects/${project.id}/archive`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
          await loadProjects();
        } catch (error) { alert.textContent = error.message; alert.hidden = false; }
      });
      row.append(archive);
      rows.append(row);
    }
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  }
  filter.addEventListener('change', loadProjects);
  await loadProjects();
}

async function renderProject(id) {
  app.replaceChildren();
  const back = element('button', 'Projects', { type: 'button' });
  back.addEventListener('click', () => go('/'));
  app.append(back);
  try {
    const project = await request(`/api/projects/${id}`);
    app.append(element('h1', project.name));
    if (project.archived) app.append(element('p', 'Archived project'));
    const renameForm = element('form');
    const renameLabel = element('label', 'New project name', { for: 'new-project-name' });
    const renameInput = element('input', undefined, { id: 'new-project-name', name: 'name', type: 'text' });
    const renameButton = element('button', 'Rename project', { type: 'submit' });
    if (project.archived) { renameInput.disabled = true; renameButton.disabled = true; }
    renameForm.append(renameLabel, renameInput, renameButton);
    const form = element('form');
    const label = element('label', 'Task title', { for: 'task-title' });
    const input = element('input', undefined, { id: 'task-title', name: 'title', type: 'text' });
    const submit = element('button', 'Create task', { type: 'submit' });
    if (project.archived) { input.disabled = true; submit.disabled = true; }
    const alert = element('p', '', { role: 'alert', hidden: '' });
    form.append(label, input, submit);

    const defaultPriorityLabel = element('label', 'Default task priority', { for: 'default-task-priority' });
    const defaultPriority = element('select', undefined, { id: 'default-task-priority' });
    for (const value of ['Low', 'Normal', 'High']) defaultPriority.append(element('option', value, { value }));
    defaultPriority.value = project.defaultPriority;
    defaultPriority.disabled = project.archived;

    const filterLabel = element('label', 'Task filter', { for: 'task-filter' });
    const filter = element('select', undefined, { id: 'task-filter' });
    for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value: value.toLowerCase() }));
    const priorityFilterLabel = element('label', 'Priority filter', { for: 'priority-filter' });
    const priorityFilter = element('select', undefined, { id: 'priority-filter' });
    for (const value of ['All', 'Low', 'Normal', 'High']) priorityFilter.append(element('option', value, { value: value.toLowerCase() }));
    const dueFromLabel = element('label', 'Due from', { for: 'due-from' });
    const dueFrom = element('input', undefined, { id: 'due-from', type: 'text' });
    const dueThroughLabel = element('label', 'Due through', { for: 'due-through' });
    const dueThrough = element('input', undefined, { id: 'due-through', type: 'text' });
    const applyDueRange = element('button', 'Apply due range', { type: 'button' });
    const rows = element('section', undefined, { 'aria-label': 'Tasks' });
    app.append(renameForm, defaultPriorityLabel, defaultPriority, form, alert, filterLabel, filter, priorityFilterLabel, priorityFilter, dueFromLabel, dueFrom, dueThroughLabel, dueThrough, applyDueRange, rows);

    defaultPriority.addEventListener('change', async () => {
      const previous = project.defaultPriority;
      defaultPriority.disabled = true;
      try {
        const updated = await request(`/api/projects/${id}/default-priority`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority: defaultPriority.value }) });
        project.defaultPriority = updated.defaultPriority;
        alert.hidden = true;
      } catch (error) {
        defaultPriority.value = previous;
        alert.textContent = error.message;
        alert.hidden = false;
      } finally {
        defaultPriority.disabled = project.archived;
      }
    });

    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      const name = renameInput.value.trim();
      if (!name) {
        alert.textContent = 'Project name is required';
        alert.hidden = false;
        renameInput.focus();
        return;
      }
      try {
        const renamed = await request(`/api/projects/${id}/name`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
        app.querySelector('h1').textContent = renamed.name;
        renameInput.value = '';
        alert.hidden = true;
      } catch (error) {
        alert.textContent = error.message;
        alert.hidden = false;
      }
    });

    let tasks = [];
    let appliedDueRange = { from: '', through: '' };
    function isValidCalendarDate(value) {
      const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
      if (!match) return false;
      const year = Number(match[1]);
      const month = Number(match[2]);
      const day = Number(match[3]);
      if (year < 1 || month < 1 || month > 12 || day < 1) return false;
      const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
      const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
      return day <= days[month - 1];
    }
    function showTasks() {
      rows.replaceChildren();
      const selected = filter.value;
      const selectedPriority = priorityFilter.value;
      for (const task of tasks) {
        if (selected === 'open' && task.completed || selected === 'completed' && !task.completed) continue;
        if (selectedPriority !== 'all' && task.priority.toLowerCase() !== selectedPriority) continue;
        if ((appliedDueRange.from || appliedDueRange.through) && !task.dueDate) continue;
        if (task.dueDate && appliedDueRange.from && task.dueDate < appliedDueRange.from) continue;
        if (task.dueDate && appliedDueRange.through && task.dueDate > appliedDueRange.through) continue;
        const row = element('article', undefined, { 'data-testid': 'task-row' });
        row.append(element('span', task.title));
        const renameForm = element('form');
        const renameInput = element('input', undefined, { type: 'text', 'aria-label': 'New task title', value: task.title });
        const renameButton = element('button', 'Rename task', { type: 'submit' });
        renameInput.disabled = project.archived;
        renameButton.disabled = project.archived;
        renameForm.append(renameInput, renameButton);
        renameForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          const title = renameInput.value.trim();
          if (!title) {
            alert.textContent = 'Task title is required';
            alert.hidden = false;
            renameInput.focus();
            return;
          }
          try {
            await request(`/api/projects/${id}/tasks/${task.id}/title`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
            task.title = title;
            alert.hidden = true;
            showTasks();
          } catch (error) {
            alert.textContent = error.message;
            alert.hidden = false;
          }
        });
        row.append(renameForm);
        const dueDateForm = element('form');
        const dueDateInput = element('input', undefined, { type: 'text', 'aria-label': 'Task due date', value: task.dueDate || '' });
        const dueDateButton = element('button', 'Save due date', { type: 'submit' });
        dueDateInput.disabled = project.archived;
        dueDateButton.disabled = project.archived;
        dueDateForm.append(dueDateInput, dueDateButton);
        dueDateForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          const dueDate = dueDateInput.value.trim();
          try {
            const updated = await request(`/api/projects/${id}/tasks/${task.id}/due-date`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ dueDate })
            });
            task.dueDate = updated.dueDate;
            dueDateInput.value = updated.dueDate || '';
            alert.hidden = true;
            showTasks();
          } catch (error) {
            alert.textContent = error.message;
            alert.hidden = false;
          }
        });
        row.append(dueDateForm);
        const priority = element('select', undefined, { 'aria-label': 'Task priority' });
        for (const value of ['Low', 'Normal', 'High']) priority.append(element('option', value, { value }));
        priority.value = task.priority;
        priority.disabled = project.archived;
        priority.addEventListener('change', async () => {
          const previous = task.priority;
          priority.disabled = true;
          try {
            await request(`/api/projects/${id}/tasks/${task.id}/priority`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority: priority.value }) });
            task.priority = priority.value;
            alert.hidden = true;
            showTasks();
          } catch (error) {
            priority.value = previous;
            alert.textContent = error.message;
            alert.hidden = false;
          } finally {
            priority.disabled = project.archived;
          }
        });
        row.append(priority);
        const checkbox = element('input', undefined, { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
        checkbox.checked = task.completed;
        checkbox.disabled = project.archived;
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          try {
            await request(`/api/projects/${id}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
            task.completed = checkbox.checked;
            showTasks();
          } catch (error) {
